module tb;
  // Clock and reset
  logic clk;
  logic rst;
  localparam int CLK_PERIOD = 8;

  // DUT ports
  logic [7:0] s_axis_tdata;
  logic s_axis_tvalid;
  logic s_axis_tready;   // output from DUT
  logic txd;             // output from DUT
  logic busy;            // output from DUT
  logic [15:0] prescale; // input to DUT

  // Clock generation
  initial clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset sequence
  initial begin
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
  end

  // Instantiate uart_tx with default DATA_WIDTH=8
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd          (txd),
    .busy         (busy),
    .prescale     (prescale)
  );

  // Drive a constant non‑zero prescale value
  initial prescale = 16'd5;

  // -------------------------------------------------
  // Task: send a byte respecting the AXI‑Stream handshake
  // -------------------------------------------------
  task automatic send_byte(input [7:0] data);
    // Wait until the DUT asserts s_axis_tready (idle)
    wait (s_axis_tready);
    @(posedge clk);
    // Assert valid and present the data
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = data;

    // Keep valid high until the DUT becomes idle again
    // (busy low and s_axis_tready high)
    while (!(busy == 0 && s_axis_tready == 1)) begin
      @(posedge clk);
    end
    // De‑assert valid on the next rising edge
    @(posedge clk);
    s_axis_tvalid = 1'b0;
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Wait until reset is released
    @(rst);

    // Give the design a few cycles to settle into an idle state
    repeat (30) @(negedge clk);

    // First frame: data = 0xC3 (must be transmitted completely)
    send_byte(8'hC3);

    // Second frame: data = 0x3C (the byte that should trigger T6 coverage)
    send_byte(8'h3C);

    // Allow enough time for the coverage property to be evaluated
    repeat (60) @(negedge clk);

    $finish;
  end

endmodule

module tb;

  // ------------------------------------------------------------------
  // Parameters and clock generation
  // ------------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                     // 125 MHz
  localparam logic [15:0] DEFAULT_PRESCALE = 16'd5; // same prescale used in regression

  // Clock and reset
  logic clk = 0;
  logic rst = 0;

  // AXI‑Stream interface signals
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;

  // Configuration input
  logic [15:0] prescale;

  // UART output signals
  logic txd;
  logic busy;

  // ------------------------------------------------------------------
  // DUT instantiation (uart_tx)
  // ------------------------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd          (txd),
    .busy         (busy),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------------
  // Clock generator
  // ------------------------------------------------------------------
  initial begin
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // ------------------------------------------------------------------
  // Simple helper tasks
  // ------------------------------------------------------------------
  task automatic wait_busy_low;
    // Wait until the transmitter becomes idle (busy = 0)
    wait (!busy);
  endtask

  task automatic wait_busy_high;
    // Wait until the transmitter becomes busy (busy = 1)
    wait (busy);
  endtask

  // ------------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------------
  initial begin
    // --- Drive configuration -------------------------------------------------
    prescale = DEFAULT_PRESCALE;

    // --- Reset --------------------------------------------------------------
    rst = 1'b1;
    #(CLK_PERIOD*10);
    rst = 1'b0;
    #(CLK_PERIOD*5);

    // --- 1) Transmit the known pattern 0xC3 ---------------------------------
    // Wait until the device is idle
    wait (busy == 0);
    // Present the first byte (8'hC3)
    @(posedge clk);
    s_axis_tdata  = 8'hC3;
    s_axis_tvalid = 1'b1;
    @(negedge clk);
    s_axis_tvalid = 1'b0;

    // Wait for the transmitter to start and finish the frame
    wait_busy_high(); // wait for busy = 1
    wait_busy_low();  // wait for busy to return to 0

    // --- 2) Load the next byte (8'h3C) that will be shifted out -------------
    // Ensure we are idle again
    wait (busy == 0);
    @(posedge clk);
    s_axis_tdata  = 8'h3C;
    s_axis_tvalid = 1'b1;
    @(negedge clk);
    s_axis_tvalid = 1'b0;

    // Wait for the second transmission to complete
    wait_busy_high();
    wait_busy_low();

    // --- Coverage point should now have been hit ---------------------------
    $finish;
  end

endmodule

