module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic [15:0] prescale = PRESCALE;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy;

  // RX tie-offs
  wire  [7:0] m_axis_tdata;
  wire        m_axis_tvalid;
  logic       m_axis_tready = 1'b1;
  logic       rxd = 1'b1;
  wire        rx_busy;
  wire        rx_overrun_error;
  wire        rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  initial begin
    int frame_clks = int'(prescale) * 80;

    do_reset();
    @(negedge clk);

    // --- First frame: shift out 8'hC3 ---
    s_axis_tdata  = 8'hC3;
    s_axis_tvalid = 1'b1;
    @(negedge clk);
    s_axis_tvalid = 1'b0;

    // Wait until the negedge immediately before the first frame's
    // end-of-stop posedge (prescale_reg==0, bit_cnt==0, tready==0).
    // The frame occupies frame_clks posedges from the load posedge;
    // we are at the negedge right after the load, so we need
    // frame_clks - 1 more negedges.
    wait_clks(frame_clks - 1);

    // --- Second frame: 8'h3C, tvalid rises on the end-of-stop clock ---
    // At this posedge: prescale_reg==0, bit_cnt==0, tready==0.
    // The DUT loads the byte; because tready_reg was 0, the non-blocking
    // assignment s_axis_tready_reg <= !s_axis_tready_reg yields 1,
    // so tready is high on the next clock (start bit, txd low).
    s_axis_tdata  = 8'h3C;
    s_axis_tvalid = 1'b1;

    // Keep tvalid asserted (axis_tvalid_held requires it while tready is low
    // after a non-handshake). The cover fires mid-frame when the second
    // byte's eight data bits have been sampled and the stop bit begins.
    wait_clks(frame_clks + 20);

    $display("PASS T6");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
